FNR==1{print "\n=== " FILENAME " ==="}
{print}
index(FILENAME,"probe_result.txt")>0 {
  if ($0 ~ /^EXIT_STATUS:/) { s=$0; sub(/^EXIT_STATUS:/,"",s); exit_status=s+0 }
  else if (length($0) && $0 !~ /^EXIT_STATUS:/) { if (!probe_line) probe_line=$0 }
}
index(FILENAME,"probe_errors.txt")>0 {
  if (length($0)) { if (errs) errs=errs "\n" $0; else errs=$0 }
}
index(FILENAME,"env_snapshot.txt")>0 {
  if ($0 ~ /^PATH=/) path=substr($0,6)
}
END{
print "\n--- Summary ---"
if (probe_line) print "probe_output: " probe_line; else print "probe_output: <empty>"
if (exit_status != "") print "exit_status: " exit_status; else print "exit_status: <missing>"
if (errs) print "probe_errors: present"; else print "probe_errors: none"
if (path) print "PATH=" path; else print "PATH: <not found in env_snapshot>"
if ((probe_line && length(probe_line)>0) || exit_status==0) print "Conclusion: npm appears present"; else print "Conclusion: npm does NOT appear present"
}
' temp_workspace/probe_result.txt temp_workspace/probe_errors.txt temp_workspace/env_snapshot.txt > temp_workspace/readiness_summary.txt
